{"description":"验收媒体尺寸可读取性及参数对应","command":"python3 - <<'PY'
import json,pathlib,struct,zlib,hashlib
m=json.load(open('manifest.json'))['items']; s=json.load(open('submission.json'))['items']; runs=json.load(open('media.json'))['runs']; inputs=json.load(open('run-inputs.json'))['runs']; out=[]
for i,(req,sub,r,inp) in enumerate(zip(m,s,runs,inputs),1):
 errors=[]; img=r['images'][0] if len(r.get('images',[]))==1 else None
 if not (r.get('status')=='succeeded' and r.get('run_id')==sub['run_id']==inp['run_id'] and r.get('request_id')==sub['request_id']==req['request_id']): errors.append('run/request mismatch or failure')
 a=inp.get('arguments',{}); params=a.get('parameters',{}); expected=req['request']['parameters']; prompt=pathlib.Path(req['parameter_files']['positive_prompt']).read_text()
 if params.get('positive_prompt')!=prompt: errors.append('prompt mismatch')
 if any(params.get(k)!=v for k,v in expected.items()) or a.get('template_id')!='1' or a.get('instance_id')!='1' or a.get('loras')!=[]: errors.append('request parameters mismatch')
 info={'index':i,'run_id':sub['run_id'],'request_id':sub['request_id'],'seed':expected['seed'],'prompt':req['parameter_files']['positive_prompt'],'media':img,'errors':errors}
 if img:
  try:
   b=pathlib.Path(img['file_path']).read_bytes(); assert b[:8]==b'\x89PNG\r\n\x1a\n'; pos=8; idat=b''; end=False
   while pos<len(b):
    n=struct.unpack('>I',b[pos:pos+4])[0]; typ=b[pos+4:pos+8]; dat=b[pos+8:pos+8+n]; crc=struct.unpack('>I',b[pos+8+n:pos+12+n])[0]; assert zlib.crc32(typ+dat)&0xffffffff==crc
    if typ==b'IHDR': w,h=struct.unpack('>II',dat[:8])
    if typ==b'IDAT': idat+=dat
    pos+=12+n
    if typ==b'IEND': end=True; break
   assert end and len(zlib.decompress(idat))>0
   info.update(width=w,height=h,sha256=hashlib.sha256(b).hexdigest(),bytes=len(b));
   if (w,h)!=(512,512): errors.append('dimension mismatch')
  except Exception as e: errors.append(f'file read/decode error: {type(e).__name__}: {e}')
 out.append(info); print(i,sub['run_id'],info.get('width'),info.get('height'), 'PASS' if not errors else errors)
pathlib.Path('acceptance.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
PY"}

